public int search(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) return mid;
        if (nums[left] <= nums[mid]) {
            if (nums[left] <= target && target < nums[mid]) right = mid - 1;
            else left = mid + 1;
        } else {
            if (nums[mid] < target && target <= nums[right]) left = mid + 1;
            else right = mid - 1;
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int lowerSize = (int) (n * 0.05);
    int upperSize = (int) (n * 0.95) - lowerSize;
    int[] lower = Arrays.copyOfRange(arr, 0, lowerSize);
    int[] upper = Arrays.copyOfRange(arr, upperSize, n);
    double lowerSum = Array.stream(lower).sum();
    double upperSum = Array.stream(upper).sum();
    double mean = (lowerSum + upperSum) / (n - lowerSize - upperSize);
    return mean;
}

