public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (dist[u] != Integer.MAX_VALUE) {
                dist[v] = Math.min(dist[v], dist[u] + 1);
            }
        }
    }
    int time = 0;
    for (int i = 0; i < n; i++) {
        time += dist[i];
        if (hasApple[i]) {
            time -= dist[i];
        }
    }
    return time;
}

public String sortString(String s) {
    String result = "";
    while (s.length() > 0) {
        // Step 1: pick the smallest character from s and append it to the result
        char smallest = s.charAt(0);
        result += smallest;
        s = s.substring(1);

        // Step 2: pick the smallest character from s which is greater than the last appended character to the result and append it
        char smaller = Character.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c > smallest && c < smaller) {
                smaller = c;
            }
        }
        if (smaller != Character.MAX_VALUE) {
            result += smaller;
            s = s.replace(String.valueOf(smaller), "");
        }

        // Step 3: pick the largest character from s and append it to the result
        char largest = s.charAt(s.length() - 1);
        result += largest;
        s = s.substring(0, s.length() - 1);

        // Step 4: pick the largest character from s which is smaller than the last appended character to the result and append it
        char larger = Character.MIN_VALUE;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < largest && c > larger) {
                larger = c;
            }
        }
        if (larger != Character.MIN_VALUE) {
            result += larger;
            s = s.replace(String.valueOf(larger), "");
        }
    }
    return result;
}

