public int minCostClimbingStairs(int[] cost) {
    int firstStepCost = cost[0];
    int secondStepCost = cost[1];
    for (int i = 2; i < cost.length; i++) {
        int currentStepCost = cost[i];
        int minPrevTwoStepsCost = Math.min(firstStepCost, secondStepCost);
        firstStepCost = secondStepCost;
        secondStepCost = currentStepCost + minPrevTwoStepsCost;
    }
    return Math.min(firstStepCost, secondStepCost);
}

