    int n = mat[0].length;
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int curr = 0;
                for (int k = i; k < m && mat[k][j] == 1; k++) {
                    curr++;
                }
                max = Math.max(max, curr);
                for (int k = j; k < n && mat[i][k] == 1; k++) {
                    curr++;
                }
                max = Math.max(max, curr);
                for (int k = i, l = j; k < m && l < n && mat[k][l] == 1; k++, l++) {
                    curr++;
                }
                max = Math.max(max, curr);
                for (int k = i, l = j; k < m && l >= 0 && mat[k][l] == 1; k++, l--) {
                    curr++;
                }
                max = Math.max(max, curr);
            }
        }
    }
    return max;
}

