public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int[] res = new int[m * n];
    int i = 0, j = 0, k = 0;
    while (i < m && j < n) {
        for (int l = 0; l < Math.min(m - i, n - j); l++) {
            res[k++] = mat[i + l][j + l];
        }
        i++;
        for (int l = 0; l < Math.min(m - i, n - j); l++) {
            res[k++] = mat[i + l][j + l];
        }
        j++;
        for (int l = 0; l < Math.min(m - i, n - j); l++) {
            res[k++] = mat[i + l][j + l];
        }
        i++;
    }
    return res;
}

public static int findSmallestInteger(int n) {
    String num = String.valueOf(n);
    int min = Integer.valueOf(num);
    int minIndex = 0;
    for (int i = 0; i < num.length(); i++) {
        for (int j = i + 1; j < num.length(); j++) {
            String temp = num.substring(i, j + 1);
            int curr = Integer.valueOf(temp);
            if (curr > n && curr < min) {
                min = curr;
                minIndex = i;
            }
        }
    }
    if (minIndex == 0) {
        return -1;
    }
    String result = "";
    for (int i = 0; i < num.length(); i++) {
        if (i == minIndex) {
            result += min;
        } else {
            result += num.charAt(i);
        }
    }
    return Integer.valueOf(result);
}

