public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(Math.min(uglyNumbers[i2] * 2, uglyNumbers[i3] * 3), uglyNumbers[i5] * 5);
        uglyNumbers[i] = nextUglyNumber;
        if (nextUglyNumber == uglyNumbers[i2] * 2) i2++;
        if (nextUglyNumber == uglyNumbers[i3] * 3) i3++;
        if (nextUglyNumber == uglyNumbers[i5] * 5) i5++;
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 1;
    char prevChar = s.charAt(0);
    int longestStreak = 1;

    for (int i = 1; i < s.length(); i++) {
        char currChar = s.charAt(i);
        if (currChar == prevChar) {
            longestStreak++;
        } else {
            longestStreak = 1;
        }
        energy = Math.max(energy, longestStreak);
        prevChar = currChar;
    }

    return energy;
}

